curl -s -X POST https://slack.com/api/conversations.history -H 'Authorization: Bearer <TOKEN>' --data 'channel=C10DWSA8HG3&oldest=1789444800&latest=1789531200&inclusive=true&limit=1000' | python3 -c "
import sys,json,datetime
d=json.load(sys.stdin)
if not d.get('ok'): print(json.dumps(d)); sys.exit()
for m in d['messages']:
